/**
 * Read model for intelligences. Config gives code + handle; everything else
 * (one-line mind, posts parsed, posting frequency) comes from the distilled
 * brain in Postgres. Until the pipeline has run, those fields are null and the
 * UI shows "—" — we never invent numbers.
 */
import { intelligences as config, type IntelligenceConfig } from "@/config/intelligences";

export type Intelligence = IntelligenceConfig & {
  /** generated by the distill step, e.g. "Buys fear, sells euphoria, never marries a bag" */
  oneLineMind: string | null;
  postsParsed: number | null;
  postsPerDay: number | null;
  /** brain version timestamp (ISO) */
  distilledAt: string | null;
};

export function getIntelligences(): Intelligence[] {
  // TODO(deliverable 6): join with `influencers` + latest `brains` row.
  return config.map((c) => ({
    ...c,
    oneLineMind: null,
    postsParsed: null,
    postsPerDay: null,
    distilledAt: null,
  }));
}

export function formatCount(n: number | null): string {
  if (n == null) return "—";
  if (n >= 1_000_000) return `${(n / 1_000_000).toFixed(1).replace(/\.0$/, "")}M`;
  if (n >= 1_000) return `${(n / 1_000).toFixed(1).replace(/\.0$/, "")}k`;
  return String(n);
}
